async function g(){try{const t=await(await fetch("http://3.139.202.192:3000/api/categories")).json();return t.ok?t.data:[]}catch(n){return console.error("Error cargando categorías:",n),[]}}const y=async({search:n="",filters:t={},page:c=1,limit:r=7})=>{try{const o=await(await fetch("http://3.139.202.192:3000/api/public/news")).json();if(!o.ok)throw new Error("Error al obtener las publicaciones");let a=(o.data||[]).filter(e=>e.post_type==="post");if(a=a.map(e=>({id:e.news_post_id,title:e.title,description:e.summary||"Sin resumen disponible.",type:e.category_name||"Documento",date:e.published_at||new Date().toISOString(),image:e.cover_image||"/img/default-publication.jpg",slug:e.slug,isFeatured:e.is_featured})),n){const e=n.toLowerCase();a=a.filter(s=>s.title.toLowerCase().includes(e)||s.description.toLowerCase().includes(e))}if(t.type&&t.type.length>0){const e=Array.isArray(t.type)?t.type:t.type.split(",");a=a.filter(s=>e.includes(s.type))}if(t.year&&t.year.length>0){const e=Array.isArray(t.year)?t.year:t.year.split(",");a=a.filter(s=>s.date?e.includes(new Date(s.date).getFullYear().toString()):!1)}const l=a.length,p=Math.ceil(l/r),u=(c-1)*r;return{data:a.slice(u,u+r),total:l,page:c,totalPages:p}}catch(i){return console.error("❌ Error en getPublications:",i),{data:[],total:0,totalPages:0,page:1}}};async function d(n){try{const c=await(await fetch(`http://3.139.202.192:3000/api/public/news/${n}`)).json();if(!c.ok)throw new Error("Publicación no encontrada");const r=c.data,i=r.files||[];return{id:r.news_post_id,title:r.title,content:r.content,type:r.category_name||"Documento",date:r.published_at||r.created_at,cover:i.find(o=>o.file_role==="cover")?.file_url||"/img/default-publication.jpg",gallery:i.filter(o=>o.file_role==="gallery").map(o=>o.file_url)}}catch(t){return console.error("Error en getPublicationBySlug:",t),null}}export{g as a,d as b,y as g};
